import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { NextConfig } from "next";

// Old listing slug -> new listing slug, published rows only (an old slug of an
// unpublished row must keep answering 404, so it is never in this file).
// Generated by scripts/slug-fix/dryrun-v3.mjs --write-redirects. Slugs are
// [a-z0-9-] only, so they are safe as literal redirect sources.
const slugRedirects: Record<string, string> = JSON.parse(
  readFileSync(join(process.cwd(), "src", "data", "slug-redirects.json"), "utf8")
);

const nextConfig: NextConfig = {
  async redirects() {
    return Object.entries(slugRedirects).map(([oldSlug, newSlug]) => ({
      source: `/dine-in-theaters/${oldSlug}`,
      destination: `/dine-in-theaters/${newSlug}`,
      permanent: true, // 308
    }));
  },
  async headers() {
    return [
      {
        // Every *.vercel.app deployment (the production alias and each
        // preview) is told not to be indexed or followed. This header is the
        // only noindex mechanism for those hosts: it is evaluated by the
        // router, not by page rendering, so it costs nothing and keeps static
        // pages static. Other hosts (dineintheaters.com, www, localhost) get
        // nothing added. Do not add a robots.txt Disallow for these hosts: a
        // blocked crawler never fetches the page, so it would never see this.
        // Next anchors the value as ^...$ against the host (no port).
        source: "/:path*",
        has: [{ type: "host", value: ".*\\.vercel\\.app" }],
        headers: [{ key: "X-Robots-Tag", value: "noindex, nofollow" }],
      },
    ];
  },
};

export default nextConfig;
